import { FC, memo, useMemo } from 'react';

import { featureToggles } from 'config/featureToggle';
import { useFeatureToggle } from 'hooks';

import { Cores, MarketShare, NetRevenue, Power, Volume } from '../Kpis';
import { MarketShareOfficial } from '../Kpis/MarketShareOfficial/MarketShareOfficial';
import { KpiSwitchProps } from './types';

const MARKET_SHARE_VERSION_STORAGE_KEY = 'market-share-version';

const safeGetMarketShareVersion = (): string | null => {
  try {
    return globalThis.localStorage?.getItem(MARKET_SHARE_VERSION_STORAGE_KEY);
  } catch {
    return null;
  }
};

const KpiSwitchComponent: FC<KpiSwitchProps> = ({
  kpi = 'volume',
  onFilterChange,
}: KpiSwitchProps) => {
  const marketShareVersion = useMemo(() => safeGetMarketShareVersion(), []);
  const [marketShareOfficialEnabled, marketShareOfficialLoading] =
    useFeatureToggle(
      featureToggles.pillar.valueCreation.submenus.performanceTool
        .marketShareOfficial.id,
    );

  if (
    marketShareVersion === 'v2' &&
    kpi === 'market_share' &&
    marketShareOfficialEnabled &&
    !marketShareOfficialLoading
  ) {
    return <MarketShareOfficial />;
  }
  switch (kpi) {
    case 'power':
      return <Power onFilterChange={onFilterChange} />;
    case 'volume':
      return <Volume onFilterChange={onFilterChange} />;
    case 'nr':
      return <NetRevenue onFilterChange={onFilterChange} />;
    case 'market_share':
      return <MarketShare onFilterChange={onFilterChange} />;
    case 'cores':
      return <Cores onFilterChange={onFilterChange} />;
    default:
      return null;
  }
};

export const KpiSwitch = memo(KpiSwitchComponent);
